 async Task Start(){if(disposed||busy)return;int w,b;if(!int.TryParse(work.Text,out w)||!int.TryParse(rest.Text,out b)||w<1||w>1440||b<1||b>1440){validationError="Choose work and break lengths from 1 to 1440 minutes.";Refresh();return;}validationError=null;var settings=new FocusSettings{defaultMinutes=w,breakMinutes=b,autoStartBreak=autoBreak.IsChecked==true,hiddenProcesses=apps.Text.Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(n=>n.Trim()).Where(n=>n.Length>0).ToArray(),blockedProcesses=new string[0],disabledWorkspaces=new string[0]};busy=true;Refresh();await FocusMode.Start(settings,goal.Text);busy=false;Refresh();}
