 internal static string Format(double seconds){int value=(int)Math.Ceiling(Math.Max(0,seconds));return value>=3600?(value/3600)+":"+((value/60)%60).ToString("00")+":"+(value%60).ToString("00"):(value/60).ToString("00")+":"+(value%60).ToString("00");}
