  double fraction=active&&state.totalSeconds>0?Math.Max(0,Math.Min(1,seconds/state.totalSeconds)):1;double angle=Math.Max(.001,Math.Min(.999999,fraction))*2*Math.PI;var geometry=new PathGeometry();var figure=new PathFigure{StartPoint=new Point(84,6),IsClosed=false};figure.Segments.Add(new ArcSegment(new Point(84+78*Math.Sin(angle),84-78*Math.Cos(angle)),new Size(78,78),0,angle>Math.PI,SweepDirection.Clockwise,true));geometry.Figures.Add(figure);progress.Data=geometry;
